  let lastX = 0;
  let lastY = 0;
  let memeIndex = 0;
  const MAX_ACTIVE = 28;

  function spawnCard(x, y, rotation, lifetime) {
    const pool = stage.querySelectorAll('.u323-p');
    if (pool.length > MAX_ACTIVE) {
      pool[0].remove();
    }

    const card = document.createElement('div');
    card.className = 'u323-p';
    card.style.setProperty('--x', x + 'px');
    card.style.setProperty('--y', y + 'px');
    card.style.setProperty('--r', (rotation || 0) + 'deg');

    const img = document.createElement('img');
    img.src = MEMES[memeIndex % MEMES.length];
    img.alt = 'Meme photo trail';
    img.loading = 'eager';
    card.appendChild(img);
    stage.appendChild(card);
    memeIndex++;

    const dur = lifetime || 1200;
    setTimeout(() => {
      card.classList.add('is-out');
      setTimeout(() => {
        if (card.parentNode) card.remove();
      }, 460);
    }, dur);
  }

  hit.addEventListener('pointermove', (e) => {
