    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const dist = Math.hypot(x - lastX, y - lastY);

    if (dist > 40) {
      lastX = x;
      lastY = y;
      const rot = (Math.random() * 36) - 18;
      spawnCard(x, y, rot, 1100);
    }
  });

  hit.addEventListener('click', (e) => {
