    const cx = e.clientX - rect.left;
    const cy = e.clientY - rect.top;

    // Fan burst 5 cards
    for (let i = 0; i < 5; i++) {
      const offsetX = (i - 2) * 22;
      const offsetY = Math.abs(i - 2) * 6;
      const rot = (i - 2) * 12;
      setTimeout(() => {
        spawnCard(cx + offsetX, cy + offsetY, rot, 1400);
      }, i * 35);
    }
  });
